"""Self-contained three-lane driving widget for Telegram's profile-1 sandbox."""

import zlib

HTML = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;background:#090611;color:#f6f1ff;font:13px system-ui,sans-serif}.game{padding:11px;border:1px solid #7541a9;border-radius:17px;background:linear-gradient(150deg,#211035,#0c0917 70%,#1b102d)}.head,.score,.controls,.legend{display:flex;align-items:center;justify-content:space-between}.head{height:25px}.brand{color:#c391ff;font-size:10px;font-weight:900;letter-spacing:1px}.badge{padding:4px 7px;border-radius:8px;background:#54217e;font-size:10px;font-weight:800}h1{font-size:17px;margin:4px 0 8px}.score{gap:7px;margin-bottom:8px}.stat{flex:1;padding:6px;border:1px solid #48305e;border-radius:9px;background:#1c122a;text-align:center}.stat b{display:block;font-size:17px}.stat small{color:#c6b2d9;font-size:10px}.gold b{color:#ffd052}.gem b{color:#86ebff}.speed b{color:#d9abff}
.road{position:relative;height:270px;overflow:hidden;border:2px solid #8649b7;border-radius:12px;background:#171120}canvas{display:block;width:100%;height:270px}.veil{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:10px;padding:16px;background:rgba(10,5,22,.93);text-align:center}.veil.hide{display:none}.veil strong{font-size:19px}.veil p{margin:0;color:#e0c9f6;font-size:11px}.start,.sync{border:1px solid #dbadff;border-radius:11px;background:#8136c9;color:white;padding:10px 23px;font-size:14px;font-weight:900;touch-action:none}.sync{font-size:11px;padding:8px 13px}.legend{margin-top:7px;color:#d9c9e6;font-size:10px}.legend .a{color:#ffcf4f}.legend .b{color:#80ebff}.legend .c{color:#ff5a72}.controls{gap:10px;margin-top:9px}.drive{flex:1;height:51px;border:1px solid #b074df;border-radius:11px;background:linear-gradient(#7137ad,#4d1d7d);color:#fff;font-size:23px;font-weight:900;touch-action:none}.drive:active,.start:active{background:#a84bea}.foot{margin-top:7px;color:#bb9fcb;text-align:center;font-size:10px}
</style></head><body><main class="game"><div class="head"><span class="brand">GOD OF DARS · DRIVE</span><span class="badge">۳ لاین</span></div><h1>فرار از موانع</h1><div class="score"><div class="stat gold"><b id="gold">۰</b><small>طلا</small></div><div class="stat gem"><b id="gem">۰</b><small>الماس</small></div><div class="stat speed"><b id="speed">۱×</b><small>سرعت</small></div></div><div class="road"><canvas id="scene" width="300" height="270"></canvas><div class="veil" id="veil"><strong id="title">آماده‌ای؟</strong><p id="hint">از موانع فرار کن و پاداش جمع کن.</p><button class="start" id="start">شروع بازی</button><button class="sync" id="sync" style="display:none">دریافت نتیجه</button></div></div><div class="legend"><span class="a">● طلا</span><span class="b">◆ الماس</span><span class="c">▰ مانع</span></div><div class="controls" dir="ltr"><button class="drive" id="left">◀ چپ</button><button class="drive" id="right">راست ▶</button></div><div class="foot" id="status">پاداش پس از برخورد به حسابت واریز می‌شود</div></main><script>
var T=window.TelegramWidget,S={},C=document.getElementById('scene').getContext('2d'),times=[],offset=0,lane=1,tick=0,gold=0,gem=0,crash=false,busy=false,lastFrame=0;
function read(v){try{return JSON.parse(v||'{}')}catch(e){return {}}}
function interval(n){return Math.max(.62,Math.round((1.25-.07*Math.floor(n/7))*100)/100)}
function event(seed,n){var v=(seed*48271+n*16807)%1000003;v=(v*69621+12345)%1000003;var l=Math.floor(v/100)%3;if(n<2)return ['coin',l,0];var r=v%100,o=Math.min(65,33+Math.floor(n/5));if(r<o){var mask=1<<l;if(n%3===0&&Math.floor(v/1000)%100<80)mask|=1<<((l+1+Math.floor(v/10000)%2)%3);return ['obstacle',l,mask]}return [r<o+25?'coin':r<o+34?'diamond':'empty',l,0]}
function due(n){while(times.length<=n){var k=times.length;times.push((k?times[k-1]:S.start_ms)+interval(k)*1000)}return times[n]}
function digits(n){return String(n).replace(/[0-9]/g,function(x){return '۰۱۲۳۴۵۶۷۸۹'[Number(x)]})}
function set(id,value){var e=document.getElementById(id);if(e.textContent!==value)e.textContent=value}
function ui(){set('gold',digits(gold));set('gem',digits(gem));set('speed',(Math.round(1.25/interval(tick)*10)/10)+'×');var veil=document.getElementById('veil'),start=document.getElementById('start'),sync=document.getElementById('sync');var ready=S.status==='ready',ended=S.status==='crashed';veil.className=ready||ended||crash?'veil':'veil hide';start.style.display=ready?'block':'none';sync.style.display=crash&&!ended?'block':'none';if(ready){set('title','آماده‌ای؟');set('hint','از موانع فرار کن و پاداش جمع کن.')}else if(ended){set('title','تصادف!');set('hint',digits(S.coin)+' طلا و '+digits(S.diamond)+' الماس به حسابت واریز شد. برای دور تازه /game را بزن.')}else if(crash){set('title','برخورد کردی!');set('hint','نتیجه در سرور ثبت می‌شود…')}set('status',ended?'پاداش واریز شد':crash?'در حال ثبت نتیجه':S.status==='active'?'با چپ و راست لاین را عوض کن':'پاداش پس از برخورد به حسابت واریز می‌شود')}
function absorb(next){if(!next||!next.status)return;if(next.id===S.id&&((S.status==='active'&&next.status==='ready')||(S.status==='crashed'&&next.status!=='crashed')||(S.status==='active'&&next.status==='active'&&next.server_ms<S.server_ms)))return;var fresh=next.id!==S.id||S.status==='ready'&&next.status==='active';if(fresh){times=[];offset=(next.server_ms||Date.now())-Date.now();tick=next.tick;gold=next.coin;gem=next.diamond;crash=false}else if(next.status==='active'){tick=Math.max(tick,next.tick);gold=Math.max(gold,next.coin);gem=Math.max(gem,next.diamond)}else{gold=next.coin;gem=next.diamond;crash=false}S=next;lane=next.lane;ui()}
function ask(action){if(!T||busy)return;busy=true;T.request('car:'+action+':'+S.id).then(function(a){busy=false;var next=read(a.result);if(next.error){lane=S.lane;set('status',next.error)}else absorb(next)},function(){busy=false;lane=S.lane;set('status','ارتباط برقرار نشد؛ دوباره بزن')})}
function steer(d){if(S.status!=='active'||crash||busy)return;var target=Math.max(0,Math.min(2,lane+d));if(target===lane)return;lane=target;ask('lane'+target)}
document.getElementById('start').addEventListener('click',function(){ask('start')});document.getElementById('sync').addEventListener('click',function(){ask('sync')});document.getElementById('left').addEventListener('click',function(){steer(-1)});document.getElementById('right').addEventListener('click',function(){steer(1)});
function road(t){C.fillStyle='#0b0913';C.fillRect(0,0,300,270);C.fillStyle='#282331';C.fillRect(17,0,266,270);C.fillStyle='#7b3caf';C.fillRect(17,0,3,270);C.fillRect(280,0,3,270);C.fillStyle='#ac8dc9';var shift=Math.floor(t/13)%42;for(var y=shift-42;y<270;y+=42){C.fillRect(99,y,2,20);C.fillRect(199,y,2,20)}}
function item(kind,x,y){if(kind==='obstacle'){C.fillStyle='#fa4a68';C.fillRect(x-25,y-19,50,38);C.fillStyle='#3b1020';C.fillRect(x-22,y-16,44,32);C.fillStyle='#ff667e';C.fillRect(x-22,y-16,44,7);C.fillRect(x-22,y+9,44,7);C.fillStyle='#fff';C.font='bold 25px system-ui';C.textAlign='center';C.fillText('✕',x,y+8)}else if(kind==='coin'){C.beginPath();C.arc(x,y,20,0,Math.PI*2);C.fillStyle='#ffcf4f';C.fill();C.lineWidth=4;C.strokeStyle='#a76112';C.stroke();C.fillStyle='#774008';C.font='bold 24px system-ui';C.textAlign='center';C.fillText('★',x,y+8)}else if(kind==='diamond'){C.beginPath();C.moveTo(x,y-23);C.lineTo(x+23,y);C.lineTo(x,y+23);C.lineTo(x-23,y);C.closePath();C.fillStyle='#79eaff';C.fill();C.lineWidth=3;C.strokeStyle='#137baf';C.stroke();C.beginPath();C.moveTo(x,y-20);C.lineTo(x-9,y);C.lineTo(x,y+20);C.lineTo(x+9,y);C.closePath();C.strokeStyle='#e2ffff';C.stroke()}}
function car(){var x=50+lane*100;C.fillStyle='#2b0e48';C.fillRect(x-26,187,52,71);C.fillStyle='#ad4ff0';C.fillRect(x-22,184,44,70);C.fillStyle='#572293';C.fillRect(x-17,191,34,58);C.fillStyle='#1a1228';C.fillRect(x-15,195,30,19);C.fillStyle='#d19dff';C.fillRect(x-20,220,40,5);C.fillStyle='#ff5d8e';C.fillRect(x-18,247,12,5);C.fillRect(x+6,247,12,5)}
function frame(stamp){if(stamp-lastFrame<33){requestAnimationFrame(frame);return}lastFrame=stamp;var t=Date.now()+offset;if(S.status==='active'&&S.start_ms){var changed=false;for(var k=0;k<64&&due(tick)<=t&&!crash;k++){var e=event(S.seed,tick),elapsed=(due(tick)-S.start_ms)/1000;if(e[2]&(1<<lane)){crash=true;changed=true;break}if(e[1]===lane){if(e[0]==='coin'){gold=Math.min(gold+1,Math.floor(elapsed*50/60));changed=true}if(e[0]==='diamond'){gem=Math.min(gem+1,Math.floor(elapsed*10/60));changed=true}}tick++}if(changed)ui()}road(t);if(S.status==='active'){for(var j=4;j>=0;j--){var n=tick+j,e2=event(S.seed,n),dt=due(n)-t,travel=interval(n)*3000;if(e2[0]==='empty'||dt<0||dt>travel)continue;var y=210-250*dt/travel;if(e2[0]==='obstacle'){for(var l=0;l<3;l++)if(e2[2]&(1<<l))item('obstacle',50+l*100,y)}else item(e2[0],50+e2[1]*100,y)}}car();requestAnimationFrame(frame)}
absorb(read(T&&T.chatData));if(T){T.onEvent('chatDataChanged',function(){absorb(read(T.chatData))});if(typeof T.setResizeAnchor==='function')T.setResizeAnchor('top');T.ready()}requestAnimationFrame(frame);
</script></body></html>"""

assert len(HTML.encode()) <= 32768 and len(zlib.compress(HTML.encode(), 9)) <= 4096
